-- TConnect 6.0 social foundation; apply only after review.
begin;
create table public.communities(id uuid primary key default gen_random_uuid(),owner uuid not null references public.profiles(id),name text not null check(length(name) between 1 and 80),description text not null default '' check(length(description)<=500),rules text not null default '' check(length(rules)<=2000),created_at timestamptz not null default now());
create table public.community_members(community uuid references public.communities(id) on delete cascade,member uuid references public.profiles(id) on delete cascade,primary key(community,member));
create table public.community_posts(id uuid primary key default gen_random_uuid(),community uuid not null references public.communities(id) on delete cascade,author uuid not null references public.profiles(id),body text not null check(length(body) between 1 and 500),created_at timestamptz not null default now());
create table public.close_friends(owner uuid references public.profiles(id) on delete cascade,friend uuid references public.profiles(id) on delete cascade,primary key(owner,friend),check(owner<>friend));
create table public.stories(id uuid primary key default gen_random_uuid(),author uuid not null references public.profiles(id),body text not null check(length(body) between 1 and 500),created_at timestamptz not null default now());
alter table public.communities enable row level security;
alter table public.community_members enable row level security;
alter table public.community_posts enable row level security;
alter table public.close_friends enable row level security;
alter table public.stories enable row level security;
revoke all on public.communities,public.community_members,public.community_posts,public.close_friends,public.stories from anon,authenticated;
grant select,delete on public.communities,public.community_members,public.community_posts,public.close_friends,public.stories to authenticated;
grant insert(owner,name,description,rules) on public.communities to authenticated;
grant insert(community,member) on public.community_members to authenticated;
grant insert(community,author,body) on public.community_posts to authenticated;
grant insert(owner,friend) on public.close_friends to authenticated;
grant insert(author,body) on public.stories to authenticated;
create policy community_read on public.communities for select to authenticated using(true);
create policy community_create on public.communities for insert to authenticated with check(owner=auth.uid());
create policy community_delete on public.communities for delete to authenticated using(owner=auth.uid());
create policy membership_read on public.community_members for select to authenticated using(true);
create policy membership_join on public.community_members for insert to authenticated with check(member=auth.uid());
create policy membership_leave on public.community_members for delete to authenticated using(member=auth.uid() or exists(select 1 from public.communities c where c.id=community and c.owner=auth.uid()));
create policy community_post_read on public.community_posts for select to authenticated using(true);
create policy community_post_create on public.community_posts for insert to authenticated with check(author=auth.uid() and (exists(select 1 from public.community_members m where m.community=community_posts.community and m.member=auth.uid()) or exists(select 1 from public.communities c where c.id=community_posts.community and c.owner=auth.uid())));
create policy community_post_delete on public.community_posts for delete to authenticated using(author=auth.uid() or exists(select 1 from public.communities c where c.id=community_posts.community and c.owner=auth.uid()));
create policy friends_read on public.close_friends for select to authenticated using(owner=auth.uid());
create policy friends_add on public.close_friends for insert to authenticated with check(owner=auth.uid());
create policy friends_remove on public.close_friends for delete to authenticated using(owner=auth.uid());
create policy stories_read on public.stories for select to authenticated using(created_at>now()-interval '24 hours' or author=auth.uid());
create policy stories_create on public.stories for insert to authenticated with check(author=auth.uid());
create policy stories_delete on public.stories for delete to authenticated using(author=auth.uid());
commit;